def is_valid_dashed_credit_card(s):
    groups = s.split('-')
    if len(groups) != 4 or any(len(g) != 4 or not g.isdigit() for g in groups):
        return False
    digits = ''.join(groups)
    total = 0
    for i, ch in enumerate(reversed(digits)):
        d = int(ch)
        if i % 2 == 1:
            d = d * 2
            if d > 9:
                d -= 9
        total += d
    return total % 10 == 0

